// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).

import { call } from './client-runtime'
export { ApiError } from './client-runtime'

export interface CalculateCommissionRequest {
  /** decimal(11,2,signed) */
  monto: number
  /** text(fixed,3,iso8859-1) */
  tipo: string
}

export interface CalculateCommissionResponse {
  /** decimal(7,2,signed) */
  comision: number
}

export interface TransferFundsRequest {
  /** text(var,10,iso8859-1) */
  origen: string
  /** text(var,10,iso8859-1) */
  destino: string
  /** decimal(11,2,signed) */
  monto: number
  /** text(fixed,3,iso8859-1) */
  tipo: string
}

export interface TransferFundsResponse {
  /** integer(32,signed) */
  numero: number
  /** decimal(7,2,signed) */
  comision: number
  /** text(var,40,iso8859-1) */
  mensaje: string
}

export interface GetTransferReceiptRequest {
  /** integer(32,signed) */
  numero: number
}

export interface GetTransferReceiptResponse {
  /** text(var,11,iso8859-1) */
  numero: string
  /** text(var,14,iso8859-1) */
  monto: string
}

export interface Api {
  /** Computes the transfer commission: 0.50 flat up to 1000.00, otherwise 0.1% rounded to 2 decimals half away from zero; capped at 5.00; then +1.00 for type INM (exact match, not subject to the cap). (rules RULE-001, RULE-002, RULE-003) */
  calculateCommission(request: CalculateCommissionRequest): Promise<CalculateCommissionResponse>
  /** Validates origin/destination accounts and balance, calculates the commission, debits origin (amount + commission), credits destination (amount), registers the transfer with the next sequential number and commits, all in one transaction. (rules RULE-005, RULE-006, RULE-007, RULE-008, RULE-009, RULE-010) */
  transferFunds(request: TransferFundsRequest): Promise<TransferFundsResponse>
  /** Returns the requested transfer number and its stored amount formatted with two decimals; the amount is an empty string, without error, when the transfer does not exist. (rules RULE-004) */
  getTransferReceipt(request: GetTransferReceiptRequest): Promise<GetTransferReceiptResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    calculateCommission: (request) => call<CalculateCommissionResponse>(fetchImpl, baseUrl, 'GET', '/api/transfers/commissions', request, false),
    transferFunds: (request) => call<TransferFundsResponse>(fetchImpl, baseUrl, 'POST', '/api/transfers/transfers', request, true),
    getTransferReceipt: (request) => call<GetTransferReceiptResponse>(fetchImpl, baseUrl, 'GET', '/api/transfers/transfers/{numero}/receipt', request, false),
  }
}
