Approved prototype of the screen (React, for its layout and texts):
```tsx
import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  Button,
  Badge,
  Alert,
  KeyBar,
  EmptyState,
} from '@nexti/ds';

type Comprobante = {
  numero: string;
  monto: string;
};

const SAMPLE: Comprobante = {
  numero: '00048213',
  monto: '$ 15.250,00',
};

export default function Comprobante({ navigate }: { navigate: (to: string) => void }) {
  // Local state to preview the states the screen can have:
  // "ok" = receipt shown, "empty" = no receipt data available.
  const [view, setView] = useState<'ok' | 'empty'>('ok');
  const data: Comprobante | null = view === 'ok' ? SAMPLE : null;

  const nuevaTransferencia = () => navigate('SCR-TRANSFERENCIA');

  return (
    <Screen
      title="Comprobante"
      code="SCR-COMPROBANTE"
      keys={
        <KeyBar
          actions={[
            {
              key: 'ENTER',
              label: 'Nueva transferencia',
              onPress: nuevaTransferencia,
              primary: true,
            },
          ]}
        />
      }
    >
      <Stack>
        {data ? (
          <>
            <Alert tone="success">
              La transferencia se registró correctamente. Conserve este comprobante.
            </Alert>

            <Card
              title="Detalle del comprobante"
              actions={<Badge>Registrada</Badge>}
            >
              <Grid columns={2}>
                <div data-field="lblNumero">
                  <Stack>
                    <span style={{ fontSize: 13, color: '#555' }}>Número</span>
                    <strong
                      style={{ fontSize: 22 }}
                      aria-label="Número de comprobante"
                    >
                      {data.numero}
                    </strong>
                  </Stack>
                </div>

                <div data-field="lblMonto">
                  <Stack>
                    <span style={{ fontSize: 13, color: '#555' }}>Monto</span>
                    <strong
                      style={{ fontSize: 22 }}
                      aria-label="Monto transferido"
                    >
                      {data.monto}
                    </strong>
                  </Stack>
                </div>
              </Grid>
            </Card>
          </>
        ) : (
          <>
            {/* Fields stay present in the DOM so the structure is always inspectable */}
            <div data-field="lblNumero" hidden />
            <div data-field="lblMonto" hidden />
            <EmptyState>
              No hay un comprobante para mostrar. Realice una transferencia para generarlo.
            </EmptyState>
          </>
        )}

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevaTransferencia}>
            Nueva transferencia
          </Button>
        </Row>

        <Card title="Vista previa del prototipo">
          <Row>
            <Button
              variant={view === 'ok' ? 'secondary' : 'ghost'}
              onClick={() => setView('ok')}
            >
              Con comprobante
            </Button>
            <Button
              variant={view === 'empty' ? 'secondary' : 'ghost'}
              onClick={() => setView('empty')}
            >
              Sin datos
            </Button>
          </Row>
        </Card>
      </Stack>
    </Screen>
  );
}
```
